import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int t = Integer.parseInt(st.nextToken());char[] queue = br.readLine().toCharArray();for (int time = 0; time < t; time++) {for (int i = 0; i < n - 1; i++) {if (queue[i] == 'B' && queue[i + 1] == 'G') {queue[i] = 'G';queue[i + 1] = 'B';i++;}}}System.out.println(new String(queue));}}